// Generated by Automated Quality Gate; review before merging.
const TaskService = require('../../src/task.service.js');

describe('TaskService', () => {
  let mockWindow;
  let taskService;
  const STORAGE_KEY = 'ai-review-tasks-v1';

  beforeEach(() => {
    mockWindow = {
      localStorage: {
        getItem: jest.fn(),
        setItem: jest.fn(),
      },
      crypto: {
        randomUUID: jest.fn(() => 'mock-uuid')
      }
    };

    // Since this is an AngularJS factory, we simulate the factory injection
    const factory = angular.module('taskApp')._invokeQueue.find(i => i[2] === 'TaskService')[2][1];
    taskService = factory(mockWindow);
  });

  describe('list (load)', () => {
    it('should return parsed tasks from localStorage', () => {
      const mockTasks = [{ id: '1', title: 'Test Task', done: false }];
      mockWindow.localStorage.getItem.mockReturnValue(JSON.stringify(mockTasks));
      expect(taskService.list()).toEqual(mockTasks);
    });

    it('should return empty array if localStorage is empty', () => {
      mockWindow.localStorage.getItem.mockReturnValue(null);
      expect(taskService.list()).toEqual([]);
    });

    it('should return empty array if data is invalid', () => {
      mockWindow.localStorage.getItem.mockReturnValue(JSON.stringify([{ invalid: 'data' }]));
      expect(taskService.list()).toEqual([]);
    });
  });

  describe('add', () => {
    it('should add a new task and save it', () => {
      const existing = [];
      const result = taskService.add(existing, 'New Task');
      expect(result).toHaveLength(1);
      expect(result[0].title).toBe('New Task');
      expect(mockWindow.localStorage.setItem).toHaveBeenCalled();
    });

    it('should throw error for empty title', () => {
      expect(() => taskService.add([], '')).toThrow('กรุณาระบุชื่องาน 1–120 ตัวอักษร');
    });

    it('should throw error for title exceeding 120 characters', () => {
      const longTitle = 'a'.repeat(121);
      expect(() => taskService.add([], longTitle)).toThrow('กรุณาระบุชื่องาน 1–120 ตัวอักษร');
    });
  });

  describe('remove', () => {
    it('should remove a task by id', () => {
      const tasks = [{ id: '1', title: 'Task 1', done: false }];
      const result = taskService.remove(tasks, '1');
      expect(result).toHaveLength(0);
      expect(mockWindow.localStorage.setItem).toHaveBeenCalledWith(STORAGE_KEY, '[]');
    });
  });

  describe('save (error handling)', () => {
    it('should throw custom error when localStorage.setItem fails', () => {
      mockWindow.localStorage.setItem.mockImplementation(() => {
        throw new Error('QuotaExceededError');
      });
      expect(() => taskService.save([])).toThrow('บันทึกไม่ได้ กรุณาตรวจสอบพื้นที่หรือสิทธิ์ของเบราว์เซอร์');
    });
  });
});
